import { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import { Menu, X, Phone, Home, Heart } from "lucide-react";
import { AnimatePresence, motion } from "framer-motion";
import { BRAND, NAV_LINKS } from "../../lib/content";
import { LuxButton } from "../common/LuxButton";
import { useFavorites } from "../../lib/useFavorites";

export const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const { pathname } = useLocation();
  const { favorites } = useFavorites();

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => setOpen(false), [pathname]);

  const solid = scrolled || pathname !== "/";

  return (
    <header
      data-testid="navbar"
      className={`fixed inset-x-0 top-0 z-50 transition-[background-color,box-shadow,backdrop-filter] duration-500 ${
        solid ? "bg-white/85 shadow-soft backdrop-blur-xl" : "bg-gradient-to-b from-navy-deep/45 to-transparent"
      }`}
    >
      <div className="container-lux flex h-20 items-center justify-between gap-6">
        <Link to="/" data-testid="brand-logo" className="flex items-center gap-3">
          <span
            className={`grid h-10 w-10 place-items-center rounded-xl border transition-colors duration-500 ${
              solid ? "border-gold/40 text-gold" : "border-white/40 text-white"
            }`}
          >
            <Home size={18} strokeWidth={1.4} />
          </span>
          <span className="leading-none">
            <span
              className={`block font-display text-xl tracking-[0.22em] transition-colors duration-500 ${
                solid ? "text-navy" : "text-white"
              }`}
            >
              {BRAND.name}
            </span>
            <span
              className={`block text-[9px] uppercase tracking-[0.34em] transition-colors duration-500 ${
                solid ? "text-neutral-500" : "text-white/70"
              }`}
            >
              {BRAND.tagline}
            </span>
          </span>
        </Link>

        <nav className="hidden items-center gap-9 lg:flex">
          {NAV_LINKS.map((link) => (
            <Link
              key={link.label}
              to={link.href}
              data-testid={`nav-link-${link.label.toLowerCase().replace(/\s+/g, "-")}`}
              className={`link-underline text-[13px] tracking-wide transition-colors duration-300 ${
                solid ? "text-neutral-700 hover:text-navy" : "text-white/85 hover:text-white"
              }`}
            >
              {link.label}
            </Link>
          ))}
        </nav>

        <div className="hidden items-center gap-6 lg:flex">
          <Link
            to="/saved"
            aria-label="Saved properties"
            data-testid="navbar-saved-link"
            className={`relative grid h-10 w-10 place-items-center rounded-full border transition-colors duration-300 ${
              solid ? "border-line text-navy hover:border-navy" : "border-white/35 text-white hover:border-white"
            }`}
          >
            <Heart size={15} strokeWidth={1.5} className={favorites.length ? "fill-gold text-gold" : ""} />
            {favorites.length > 0 && (
              <span
                data-testid="navbar-saved-count"
                className="absolute -right-1 -top-1 grid h-5 min-w-5 place-items-center rounded-full bg-navy px-1 text-[10px] text-white"
              >
                {favorites.length}
              </span>
            )}
          </Link>
          <a
            href={`tel:${BRAND.phone.replace(/[^+\d]/g, "")}`}
            data-testid="navbar-phone"
            className={`flex items-center gap-2 text-[13px] transition-colors duration-300 ${
              solid ? "text-navy" : "text-white"
            }`}
          >
            <Phone size={14} strokeWidth={1.5} className="text-gold" />
            {BRAND.phone}
          </a>
          <LuxButton as="a" href="/#contact" size="sm" data-testid="navbar-cta">
            Book Consultation
          </LuxButton>
        </div>

        <button
          type="button"
          aria-label="Toggle navigation"
          data-testid="mobile-menu-toggle"
          onClick={() => setOpen((v) => !v)}
          className={`grid h-11 w-11 place-items-center rounded-full border lg:hidden ${
            solid ? "border-line text-navy" : "border-white/40 text-white"
          }`}
        >
          {open ? <X size={18} /> : <Menu size={18} />}
        </button>
      </div>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
            className="overflow-hidden border-t border-line bg-white lg:hidden"
            data-testid="mobile-menu"
          >
            <div className="container-lux flex flex-col gap-1 py-6">
              {NAV_LINKS.map((link) => (
                <Link
                  key={link.label}
                  to={link.href}
                  data-testid={`mobile-nav-${link.label.toLowerCase().replace(/\s+/g, "-")}`}
                  className="border-b border-line/70 py-3 text-sm text-neutral-700"
                >
                  {link.label}
                </Link>
              ))}
              <Link
                to="/saved"
                data-testid="mobile-nav-saved"
                className="border-b border-line/70 py-3 text-sm text-neutral-700"
              >
                Saved Properties {favorites.length > 0 ? `(${favorites.length})` : ""}
              </Link>
              <LuxButton as="a" href="/#contact" className="mt-5 w-full" data-testid="mobile-cta">
                Book Consultation
              </LuxButton>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
};
