import { useMemo, useState } from "react";
import { Slider } from "../ui/slider";
import { Reveal } from "../common/Reveal";
import { LuxButton } from "../common/LuxButton";
import { formatPrice } from "../../lib/api";

const Row = ({ label, value, min, max, step, onChange, testId, suffix = "" }) => (
  <div>
    <div className="flex items-baseline justify-between">
      <label className="text-[11px] uppercase tracking-[0.18em] text-neutral-500">{label}</label>
      <span className="font-display text-lg text-navy" data-testid={`${testId}-value`}>
        {suffix === "$" ? formatPrice(value) : `${value}${suffix}`}
      </span>
    </div>
    <Slider
      className="mt-4"
      value={[value]}
      min={min}
      max={max}
      step={step}
      onValueChange={(v) => onChange(v[0])}
      data-testid={testId}
      aria-label={label}
    />
  </div>
);

export const MortgageCalculator = () => {
  const [price, setPrice] = useState(2500000);
  const [downPct, setDownPct] = useState(20);
  const [rate, setRate] = useState(5.5);
  const [years, setYears] = useState(30);

  const { monthly, principal, totalInterest } = useMemo(() => {
    const p = price * (1 - downPct / 100);
    const r = rate / 100 / 12;
    const n = years * 12;
    const m = r === 0 ? p / n : (p * r) / (1 - Math.pow(1 + r, -n));
    return { monthly: m, principal: p, totalInterest: m * n - p };
  }, [price, downPct, rate, years]);

  return (
    <section className="bg-beige py-24 lg:py-32" data-testid="mortgage-section">
      <div className="container-lux grid items-center gap-14 lg:grid-cols-2">
        <Reveal>
          <p className="overline">Mortgage Calculator</p>
          <h2 className="mt-4 text-3xl font-light leading-[1.1] tracking-tight text-navy sm:text-4xl lg:text-[44px]">
            Understand the Numbers Before You Offer
          </h2>
          <p className="mt-6 max-w-lg text-base leading-relaxed text-neutral-600">
            Model your monthly commitment in seconds, then speak to our finance desk about indicative private-bank terms.
          </p>
          <div className="mt-10 space-y-7 rounded-2xl border border-line bg-white p-8 shadow-soft">
            <Row label="Property Price" value={price} min={250000} max={10000000} step={50000} onChange={setPrice} testId="mortgage-price" suffix="$" />
            <Row label="Down Payment" value={downPct} min={5} max={60} step={1} onChange={setDownPct} testId="mortgage-down" suffix="%" />
            <Row label="Interest Rate" value={rate} min={1} max={12} step={0.1} onChange={setRate} testId="mortgage-rate" suffix="%" />
            <Row label="Loan Duration" value={years} min={5} max={40} step={1} onChange={setYears} testId="mortgage-years" suffix=" yrs" />
          </div>
        </Reveal>

        <Reveal delay={0.12}>
          <div className="relative overflow-hidden rounded-2xl bg-navy p-10 text-white shadow-lift">
            <div className="absolute -right-16 -top-16 h-56 w-56 rounded-full bg-gold/15 blur-3xl" />
            <p className="relative text-[11px] uppercase tracking-[0.2em] text-white/60">Estimated Monthly Payment</p>
            <p className="relative mt-4 font-display text-5xl font-light text-gold-light lg:text-6xl" data-testid="mortgage-monthly">
              {formatPrice(monthly)}
            </p>
            <div className="relative mt-10 space-y-5 border-t border-white/10 pt-8 text-sm">
              <div className="flex justify-between">
                <span className="text-white/60">Loan amount</span>
                <span data-testid="mortgage-principal">{formatPrice(principal)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/60">Down payment</span>
                <span>{formatPrice(price - principal)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/60">Total interest</span>
                <span>{formatPrice(totalInterest)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-white/60">Total repayable</span>
                <span>{formatPrice(principal + totalInterest)}</span>
              </div>
            </div>
            <LuxButton as="a" href="#contact" variant="gold" className="relative mt-10 w-full" data-testid="mortgage-cta">
              Speak to Finance Desk
            </LuxButton>
          </div>
        </Reveal>
      </div>
    </section>
  );
};
