import { Reveal } from "./Reveal";

export const SectionHeading = ({ overline, title, description, align = "left", light = false, action }) => (
  <div
    className={`flex flex-col gap-5 ${align === "center" ? "items-center text-center mx-auto max-w-2xl" : "items-start"} ${
      action ? "md:flex-row md:items-end md:justify-between md:gap-12" : ""
    }`}
  >
    <Reveal className={align === "center" ? "" : "max-w-2xl"}>
      <p className="overline">{overline}</p>
      <h2
        className={`mt-4 text-3xl sm:text-4xl lg:text-[44px] leading-[1.1] tracking-tight font-light ${
          light ? "text-white" : "text-navy"
        }`}
      >
        {title}
      </h2>
      {description && (
        <p className={`mt-5 text-base leading-relaxed ${light ? "text-white/70" : "text-neutral-600"}`}>{description}</p>
      )}
    </Reveal>
    {action && <Reveal delay={0.12}>{action}</Reveal>}
  </div>
);
