import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { motion, useScroll, useTransform } from "framer-motion";
import { MapPin, Search, ChevronDown } from "lucide-react";
import { LuxButton } from "../common/LuxButton";
import { PRICE_RANGES, PROPERTY_TYPES } from "../../lib/content";

const HERO_IMAGE =
  "https://images.unsplash.com/photo-1767950470198-c9cd97f8ed87?crop=entropy&cs=srgb&fm=jpg&q=85&w=2000";

const Field = ({ label, children }) => (
  <div className="flex flex-col gap-2 px-5 py-4 md:px-6">
    <span className="text-[10px] uppercase tracking-[0.2em] text-neutral-500">{label}</span>
    {children}
  </div>
);

const selectClass =
  "w-full appearance-none bg-transparent pr-6 text-sm text-navy focus:outline-none cursor-pointer";

export const Hero = () => {
  const navigate = useNavigate();
  const { scrollY } = useScroll();
  const imageY = useTransform(scrollY, [0, 700], [0, 140]);
  const textY = useTransform(scrollY, [0, 700], [0, 60]);

  const [filters, setFilters] = useState({ location: "", type: "All Types", beds: "Any", price: 0 });

  const onSearch = (event) => {
    event.preventDefault();
    const range = PRICE_RANGES[filters.price];
    const params = new URLSearchParams();
    if (filters.location) params.set("location", filters.location);
    if (filters.type !== "All Types") params.set("type", filters.type);
    if (filters.beds !== "Any") params.set("beds", filters.beds);
    if (range.min) params.set("min_price", range.min);
    if (range.max) params.set("max_price", range.max);
    navigate(`/properties?${params.toString()}`);
  };

  return (
    <section className="relative min-h-[94vh] overflow-hidden bg-navy-deep" data-testid="hero-section">
      <motion.div style={{ y: imageY }} className="absolute inset-0 -top-24 h-[115%]">
        <img src={HERO_IMAGE} alt="Luxury villa at dusk" className="h-full w-full object-cover" />
        <div className="absolute inset-0 bg-gradient-to-r from-navy-deep/85 via-navy-deep/45 to-transparent" />
        <div className="absolute inset-0 bg-gradient-to-t from-white/95 via-transparent to-transparent" />
      </motion.div>

      <motion.div style={{ y: textY }} className="container-lux relative flex min-h-[94vh] flex-col justify-center pb-56 pt-32">
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.15 }}
          className="overline text-gold-light"
        >
          Find Your Dream Home
        </motion.p>

        <motion.h1
          initial={{ opacity: 0, y: 34 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1, delay: 0.28, ease: [0.22, 1, 0.36, 1] }}
          className="mt-6 max-w-3xl font-display text-4xl font-light leading-[1.05] tracking-tight text-white sm:text-5xl lg:text-[76px]"
        >
          Discover Luxury<br />
          <span className="italic text-gold-light">Living,</span> Redefined
        </motion.h1>

        <motion.p
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.9, delay: 0.45 }}
          className="mt-7 max-w-xl text-base leading-relaxed text-white/75"
        >
          An invitation-only portfolio of the world's finest residences, represented with the discretion and precision
          our clients expect.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 24 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.9, delay: 0.6 }}
          className="mt-10 flex flex-wrap gap-4"
        >
          <LuxButton as="a" href="/properties" size="lg" data-testid="hero-explore-btn">
            Explore Properties
          </LuxButton>
          <LuxButton as="a" href="#contact" variant="ghost" size="lg" data-testid="hero-consultation-btn">
            Book Consultation
          </LuxButton>
        </motion.div>
      </motion.div>

      <motion.form
        onSubmit={onSearch}
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1, delay: 0.75, ease: [0.22, 1, 0.36, 1] }}
        data-testid="hero-search-form"
        className="container-lux absolute inset-x-0 bottom-10 z-10"
      >
        <div className="glass grid divide-y divide-line rounded-2xl shadow-lift md:grid-cols-[1.2fr_1fr_0.8fr_1fr_auto] md:divide-x md:divide-y-0">
          <Field label="Location">
            <div className="flex items-center gap-2">
              <MapPin size={15} strokeWidth={1.5} className="text-gold" />
              <input
                value={filters.location}
                onChange={(e) => setFilters({ ...filters, location: e.target.value })}
                placeholder="City or neighbourhood"
                data-testid="search-location-input"
                className="w-full bg-transparent text-sm text-navy placeholder:text-neutral-400 focus:outline-none"
              />
            </div>
          </Field>

          <Field label="Property Type">
            <div className="relative flex items-center">
              <select
                value={filters.type}
                onChange={(e) => setFilters({ ...filters, type: e.target.value })}
                data-testid="search-type-select"
                className={selectClass}
              >
                {PROPERTY_TYPES.map((t) => (
                  <option key={t}>{t}</option>
                ))}
              </select>
              <ChevronDown size={14} className="pointer-events-none absolute right-0 text-neutral-400" />
            </div>
          </Field>

          <Field label="Bedrooms">
            <div className="relative flex items-center">
              <select
                value={filters.beds}
                onChange={(e) => setFilters({ ...filters, beds: e.target.value })}
                data-testid="search-beds-select"
                className={selectClass}
              >
                {["Any", "2", "3", "4", "5", "6"].map((b) => (
                  <option key={b}>{b}</option>
                ))}
              </select>
              <ChevronDown size={14} className="pointer-events-none absolute right-0 text-neutral-400" />
            </div>
          </Field>

          <Field label="Price Range">
            <div className="relative flex items-center">
              <select
                value={filters.price}
                onChange={(e) => setFilters({ ...filters, price: Number(e.target.value) })}
                data-testid="search-price-select"
                className={selectClass}
              >
                {PRICE_RANGES.map((r, i) => (
                  <option key={r.label} value={i}>
                    {r.label}
                  </option>
                ))}
              </select>
              <ChevronDown size={14} className="pointer-events-none absolute right-0 text-neutral-400" />
            </div>
          </Field>

          <div className="p-4">
            <LuxButton type="submit" className="h-full w-full md:w-auto" data-testid="search-submit-btn">
              <Search size={15} strokeWidth={1.6} /> Search
            </LuxButton>
          </div>
        </div>
      </motion.form>
    </section>
  );
};
