import { useState } from "react";
import { Link } from "react-router-dom";
import { Home, Linkedin, Instagram, Twitter, Facebook, ArrowRight } from "lucide-react";
import { toast } from "sonner";
import { BRAND, NAV_LINKS, SERVICES } from "../../lib/content";
import { subscribe } from "../../lib/api";

const SOCIALS = [Linkedin, Instagram, Twitter, Facebook];

export const Footer = () => {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubscribe = async (event) => {
    event.preventDefault();
    setLoading(true);
    try {
      const res = await subscribe(email);
      toast.success(res.message);
      setEmail("");
    } catch {
      toast.error("Please enter a valid email address.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <footer className="relative overflow-hidden bg-navy-deep text-white" data-testid="footer">
      <div className="container-lux grid gap-14 py-20 md:grid-cols-2 lg:grid-cols-4">
        <div>
          <div className="flex items-center gap-3">
            <span className="grid h-10 w-10 place-items-center rounded-xl border border-gold/40 text-gold">
              <Home size={18} strokeWidth={1.4} />
            </span>
            <span>
              <span className="block font-display text-xl tracking-[0.22em]">{BRAND.name}</span>
              <span className="block text-[9px] uppercase tracking-[0.34em] text-white/60">{BRAND.tagline}</span>
            </span>
          </div>
          <p className="mt-6 text-sm leading-relaxed text-white/60">
            An advisory practice for exceptional homes. Representing buyers and sellers across 35 cities with discretion
            and precision.
          </p>
          <div className="mt-7 flex gap-3">
            {SOCIALS.map((Icon, i) => (
              <a
                key={i}
                href="#contact"
                aria-label="Social profile"
                data-testid={`footer-social-${i}`}
                className="grid h-10 w-10 place-items-center rounded-full border border-white/15 text-white/70 transition-[background-color,color,border-color] duration-300 hover:border-gold hover:bg-gold hover:text-navy-deep"
              >
                <Icon size={15} strokeWidth={1.5} />
              </a>
            ))}
          </div>
        </div>

        <div>
          <h3 className="text-sm uppercase tracking-[0.2em] text-gold">Quick Links</h3>
          <ul className="mt-6 space-y-3">
            {NAV_LINKS.map((link) => (
              <li key={link.label}>
                <Link
                  to={link.href}
                  data-testid={`footer-link-${link.label.toLowerCase().replace(/\s+/g, "-")}`}
                  className="text-sm text-white/60 transition-colors duration-300 hover:text-gold"
                >
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h3 className="text-sm uppercase tracking-[0.2em] text-gold">Services</h3>
          <ul className="mt-6 space-y-3">
            {SERVICES.map((service) => (
              <li key={service} className="text-sm text-white/60">
                {service}
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h3 className="text-sm uppercase tracking-[0.2em] text-gold">Newsletter</h3>
          <p className="mt-6 text-sm leading-relaxed text-white/60">
            Off-market releases and market intelligence, once a month.
          </p>
          <form onSubmit={onSubscribe} className="mt-6" data-testid="newsletter-form">
            <div className="flex items-center gap-2 rounded-full border border-white/15 bg-white/5 p-1.5 focus-within:border-gold">
              <input
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Your email address"
                data-testid="newsletter-input"
                className="w-full bg-transparent px-4 text-sm text-white placeholder:text-white/40 focus:outline-none"
              />
              <button
                type="submit"
                disabled={loading}
                aria-label="Subscribe"
                data-testid="newsletter-submit"
                className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-gold text-navy-deep transition-transform duration-300 hover:scale-105 disabled:opacity-60"
              >
                <ArrowRight size={16} strokeWidth={1.6} />
              </button>
            </div>
          </form>
          <p className="mt-7 text-sm text-white/60">{BRAND.address}</p>
        </div>
      </div>

      <div className="border-t border-white/10">
        <div className="container-lux flex flex-col items-center justify-between gap-3 py-6 text-xs text-white/40 sm:flex-row">
          <p>© {new Date().getFullYear()} {BRAND.name} Real Estate. All rights reserved.</p>
          <p className="flex gap-6">
            <span>Privacy Policy</span>
            <span>Terms of Service</span>
          </p>
        </div>
      </div>
    </footer>
  );
};
