import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { AnimatePresence, motion } from "framer-motion";
import { Quote, Star, ChevronLeft, ChevronRight } from "lucide-react";
import { fetchTestimonials } from "../../lib/api";
import { SectionHeading } from "../common/SectionHeading";

export const Testimonials = () => {
  const { data: items = [] } = useQuery({ queryKey: ["testimonials"], queryFn: fetchTestimonials });
  const [index, setIndex] = useState(0);
  const active = items[index];

  const move = (dir) => setIndex((prev) => (prev + dir + items.length) % items.length);

  return (
    <section className="relative overflow-hidden bg-navy py-24 lg:py-32" data-testid="testimonials-section">
      <div className="absolute -left-24 top-10 h-72 w-72 rounded-full bg-gold/10 blur-3xl" />
      <div className="container-lux relative grid gap-14 lg:grid-cols-[0.8fr_1.2fr]">
        <SectionHeading
          overline="Testimonials"
          title="What Our Clients Say"
          description="Nine in ten of our clients come from a referral. These are their words."
          light
        />

        <div>
          <AnimatePresence mode="wait">
            {active && (
              <motion.blockquote
                key={active.id}
                initial={{ opacity: 0, y: 24 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -18 }}
                transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
                className="rounded-2xl border border-white/12 bg-white/[0.06] p-9 backdrop-blur-xl"
                data-testid="testimonial-card"
              >
                <Quote size={30} strokeWidth={1.2} className="text-gold" />
                <p className="mt-6 font-display text-2xl font-light italic leading-relaxed text-white/90 lg:text-[28px]">
                  “{active.quote}”
                </p>
                <div className="mt-8 flex items-center gap-4 border-t border-white/10 pt-7">
                  <img src={active.image} alt={active.name} loading="lazy" className="h-14 w-14 rounded-full object-cover" />
                  <div>
                    <p className="text-sm text-white">{active.name}</p>
                    <p className="mt-0.5 text-xs text-white/50">{active.role}</p>
                  </div>
                  <div className="ml-auto flex gap-1">
                    {Array.from({ length: active.rating }).map((_, i) => (
                      <Star key={i} size={14} className="fill-gold text-gold" />
                    ))}
                  </div>
                </div>
              </motion.blockquote>
            )}
          </AnimatePresence>

          <div className="mt-8 flex items-center gap-6">
            <button
              type="button"
              aria-label="Previous testimonial"
              onClick={() => move(-1)}
              data-testid="testimonial-prev"
              className="grid h-11 w-11 place-items-center rounded-full border border-white/20 text-white transition-colors duration-300 hover:border-gold hover:bg-gold hover:text-navy-deep"
            >
              <ChevronLeft size={17} strokeWidth={1.5} />
            </button>
            <button
              type="button"
              aria-label="Next testimonial"
              onClick={() => move(1)}
              data-testid="testimonial-next"
              className="grid h-11 w-11 place-items-center rounded-full border border-white/20 text-white transition-colors duration-300 hover:border-gold hover:bg-gold hover:text-navy-deep"
            >
              <ChevronRight size={17} strokeWidth={1.5} />
            </button>
            <div className="flex gap-2">
              {items.map((item, i) => (
                <button
                  key={item.id}
                  type="button"
                  aria-label={`Go to testimonial ${i + 1}`}
                  onClick={() => setIndex(i)}
                  data-testid={`testimonial-dot-${i}`}
                  className={`h-1.5 rounded-full transition-[width,background-color] duration-300 ${
                    i === index ? "w-8 bg-gold" : "w-2 bg-white/25"
                  }`}
                />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};
