import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { fetchProperties } from "../../lib/api";
import { SectionHeading } from "../common/SectionHeading";
import { StaggerGroup } from "../common/Reveal";
import { PropertyCard, PropertyCardSkeleton } from "../PropertyCard";
import { QuickViewModal } from "../QuickViewModal";
import { useFavorites } from "../../lib/useFavorites";

const TABS = ["All", "Villas", "Apartments", "Luxury Homes", "Commercial", "Land"];

export const LatestListings = () => {
  const [tab, setTab] = useState("All");
  const { data, isLoading } = useQuery({
    queryKey: ["properties", "latest", tab],
    queryFn: () => fetchProperties({ tag: tab, limit: 6, sort: "recent" }),
  });
  const { isFavorite, toggle } = useFavorites();
  const [quickView, setQuickView] = useState(null);

  return (
    <section id="listings" className="bg-offwhite py-24 lg:py-32" data-testid="latest-listings-section">
      <div className="container-lux">
        <SectionHeading
          overline="Latest Listings"
          title="Newly Represented This Month"
          description="Fresh to market, updated as our advisors bring new homes forward."
        />

        <div className="mt-10 flex flex-wrap gap-2 border-b border-line" data-testid="listing-tabs">
          {TABS.map((item) => (
            <button
              key={item}
              type="button"
              onClick={() => setTab(item)}
              data-testid={`listing-tab-${item.toLowerCase().replace(/\s+/g, "-")}`}
              className={`relative px-5 pb-4 text-[12px] uppercase tracking-[0.16em] transition-colors duration-300 ${
                tab === item ? "text-navy" : "text-neutral-400 hover:text-navy"
              }`}
            >
              {item}
              {tab === item && <span className="absolute inset-x-3 -bottom-px h-[2px] bg-gold" />}
            </button>
          ))}
        </div>

        <StaggerGroup key={`${tab}-${isLoading}`} className="mt-12 grid gap-7 sm:grid-cols-2 lg:grid-cols-3">
          {isLoading
            ? Array.from({ length: 3 }).map((_, i) => <PropertyCardSkeleton key={i} />)
            : data?.items.map((property, index) => (
                <PropertyCard
                  key={property.id}
                  property={property}
                  index={index}
                  isFavorite={isFavorite(property.id)}
                  onToggleFavorite={toggle}
                  onQuickView={setQuickView}
                />
              ))}
        </StaggerGroup>

        {!isLoading && data?.items.length === 0 && (
          <p className="mt-12 text-sm text-neutral-500" data-testid="latest-empty">
            No listings in this collection right now.
          </p>
        )}
      </div>

      <QuickViewModal property={quickView} open={Boolean(quickView)} onOpenChange={() => setQuickView(null)} />
    </section>
  );
};
