import { useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ArrowUpRight } from "lucide-react";
import { fetchProperties } from "../../lib/api";
import { SectionHeading } from "../common/SectionHeading";
import { StaggerGroup } from "../common/Reveal";
import { PropertyCard, PropertyCardSkeleton } from "../PropertyCard";
import { QuickViewModal } from "../QuickViewModal";
import { useFavorites } from "../../lib/useFavorites";

export const FeaturedProperties = () => {
  const { data, isLoading } = useQuery({
    queryKey: ["properties", "featured"],
    queryFn: () => fetchProperties({ featured: true, limit: 4 }),
  });
  const { isFavorite, toggle } = useFavorites();
  const [quickView, setQuickView] = useState(null);

  return (
    <section id="featured" className="bg-white py-24 lg:py-32" data-testid="featured-section">
      <div className="container-lux">
        <SectionHeading
          overline="Featured Properties"
          title="Handpicked Luxury Residences"
          description="A curated selection of the most compelling homes currently represented by our advisors."
          action={
            <Link
              to="/properties"
              data-testid="featured-view-all"
              className="link-underline flex items-center gap-2 text-[12px] uppercase tracking-[0.18em] text-navy"
            >
              View All Properties <ArrowUpRight size={15} strokeWidth={1.5} />
            </Link>
          }
        />

        <StaggerGroup key={isLoading ? "loading" : "ready"} className="mt-14 grid gap-7 sm:grid-cols-2 lg:grid-cols-4">
          {isLoading
            ? Array.from({ length: 4 }).map((_, i) => <PropertyCardSkeleton key={i} />)
            : data?.items.map((property, index) => (
                <PropertyCard
                  key={property.id}
                  property={property}
                  index={index}
                  isFavorite={isFavorite(property.id)}
                  onToggleFavorite={toggle}
                  onQuickView={setQuickView}
                />
              ))}
        </StaggerGroup>
      </div>

      <QuickViewModal property={quickView} open={Boolean(quickView)} onOpenChange={() => setQuickView(null)} />
    </section>
  );
};
