import axios from "axios";

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
export const API = `${BACKEND_URL}/api`;

export const http = axios.create({ baseURL: API });

export const fetchProperties = async (params = {}) => {
  const { data } = await http.get("/properties", { params });
  return data;
};

export const fetchProperty = async (id) => {
  const { data } = await http.get(`/properties/${id}`);
  return data;
};

export const fetchAgents = async () => (await http.get("/agents")).data;
export const fetchTestimonials = async () => (await http.get("/testimonials")).data;
export const fetchPosts = async () => (await http.get("/posts")).data;
export const fetchPost = async (id) => (await http.get(`/posts/${id}`)).data;
export const fetchPropertiesByIds = async (ids) =>
  (await http.get("/properties", { params: { ids: ids.join(","), limit: 60 } })).data;
export const fetchStats = async () => (await http.get("/stats")).data;
export const sendContact = async (payload) => (await http.post("/contact", payload)).data;
export const subscribe = async (email) => (await http.post("/newsletter", { email })).data;

export const formatPrice = (value) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value);

export const formatArea = (value) => new Intl.NumberFormat("en-US").format(value);
