import { useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ChevronDown, SlidersHorizontal, ChevronRight } from "lucide-react";
import { fetchProperties } from "../lib/api";
import { PROPERTY_TYPES, PRICE_RANGES } from "../lib/content";
import { PropertyCard, PropertyCardSkeleton } from "../components/PropertyCard";
import { QuickViewModal } from "../components/QuickViewModal";
import { useFavorites } from "../lib/useFavorites";
import { StaggerGroup } from "../components/common/Reveal";
import { LuxButton } from "../components/common/LuxButton";

const PAGE_SIZE = 9;

const selectClass =
  "w-full appearance-none rounded-xl border border-line bg-white px-4 py-3 pr-9 text-sm text-navy cursor-pointer focus:border-navy focus:outline-none";

export default function Properties() {
  const [params, setParams] = useSearchParams();
  const [page, setPage] = useState(0);
  const [quickView, setQuickView] = useState(null);
  const { isFavorite, toggle } = useFavorites();

  const location = params.get("location") || "";
  const type = params.get("type") || "All Types";
  const beds = params.get("beds") || "Any";
  const sort = params.get("sort") || "recent";
  const minPrice = params.get("min_price");
  const maxPrice = params.get("max_price");

  const priceIndex = PRICE_RANGES.findIndex(
    (r) => String(r.min || "") === String(minPrice || "") && String(r.max || "") === String(maxPrice || "")
  );

  const update = (patch) => {
    const next = new URLSearchParams(params);
    Object.entries(patch).forEach(([key, value]) => {
      if (value === undefined || value === "" || value === "All Types" || value === "Any") next.delete(key);
      else next.set(key, value);
    });
    setPage(0);
    setParams(next);
  };

  const query = {
    location: location || undefined,
    type: type !== "All Types" ? type : undefined,
    beds: beds !== "Any" ? Number(beds) : undefined,
    min_price: minPrice || undefined,
    max_price: maxPrice || undefined,
    sort,
    limit: PAGE_SIZE,
    skip: page * PAGE_SIZE,
  };

  const { data, isLoading } = useQuery({ queryKey: ["properties", "list", query], queryFn: () => fetchProperties(query) });
  const total = data?.total || 0;
  const pages = Math.ceil(total / PAGE_SIZE);

  return (
    <main className="pt-20" data-testid="properties-page">
      <section className="border-b border-line bg-beige py-16">
        <div className="container-lux">
          <nav className="flex items-center gap-2 text-xs text-neutral-500" data-testid="breadcrumbs">
            <Link to="/" className="hover:text-navy">
              Home
            </Link>
            <ChevronRight size={13} />
            <span className="text-navy">Properties</span>
          </nav>
          <h1 className="mt-6 font-display text-4xl font-light leading-tight tracking-tight text-navy sm:text-5xl">
            The Portfolio
          </h1>
          <p className="mt-4 max-w-xl text-base text-neutral-600">
            {total} residences currently represented across our global network.
          </p>
        </div>
      </section>

      <section className="border-b border-line bg-white py-6">
        <div className="container-lux flex flex-wrap items-center gap-4">
          <span className="flex items-center gap-2 text-[11px] uppercase tracking-[0.18em] text-neutral-500">
            <SlidersHorizontal size={14} strokeWidth={1.5} className="text-gold" /> Filters
          </span>
          <input
            value={location}
            onChange={(e) => update({ location: e.target.value })}
            placeholder="Location"
            data-testid="filter-location"
            className="w-full rounded-xl border border-line px-4 py-3 text-sm text-navy placeholder:text-neutral-400 focus:border-navy focus:outline-none sm:w-48"
          />
          <div className="relative w-full sm:w-44">
            <select value={type} onChange={(e) => update({ type: e.target.value })} className={selectClass} data-testid="filter-type">
              {PROPERTY_TYPES.map((t) => (
                <option key={t}>{t}</option>
              ))}
            </select>
            <ChevronDown size={14} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400" />
          </div>
          <div className="relative w-full sm:w-36">
            <select value={beds} onChange={(e) => update({ beds: e.target.value })} className={selectClass} data-testid="filter-beds">
              {["Any", "2", "3", "4", "5", "6"].map((b) => (
                <option key={b}>{b}</option>
              ))}
            </select>
            <ChevronDown size={14} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400" />
          </div>
          <div className="relative w-full sm:w-44">
            <select
              value={priceIndex >= 0 ? priceIndex : 0}
              onChange={(e) => {
                const range = PRICE_RANGES[Number(e.target.value)];
                update({ min_price: range.min, max_price: range.max });
              }}
              className={selectClass}
              data-testid="filter-price"
            >
              {PRICE_RANGES.map((r, i) => (
                <option key={r.label} value={i}>
                  {r.label}
                </option>
              ))}
            </select>
            <ChevronDown size={14} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400" />
          </div>
          <div className="relative w-full sm:ml-auto sm:w-48">
            <select value={sort} onChange={(e) => update({ sort: e.target.value })} className={selectClass} data-testid="filter-sort">
              <option value="recent">Newest first</option>
              <option value="price_desc">Price: high to low</option>
              <option value="price_asc">Price: low to high</option>
              <option value="area">Largest area</option>
            </select>
            <ChevronDown size={14} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-neutral-400" />
          </div>
        </div>
      </section>

      <section className="bg-offwhite py-16 lg:py-24">
        <div className="container-lux">
          <StaggerGroup key={`${page}-${type}-${sort}-${location}-${isLoading}`} className="grid gap-7 sm:grid-cols-2 lg:grid-cols-3">
            {isLoading
              ? Array.from({ length: 6 }).map((_, i) => <PropertyCardSkeleton key={i} />)
              : data?.items.map((property, index) => (
                  <PropertyCard
                    key={property.id}
                    property={property}
                    index={index}
                    isFavorite={isFavorite(property.id)}
                    onToggleFavorite={toggle}
                    onQuickView={setQuickView}
                  />
                ))}
          </StaggerGroup>

          {!isLoading && total === 0 && (
            <div className="rounded-2xl border border-line bg-white p-16 text-center" data-testid="properties-empty">
              <h2 className="font-display text-2xl text-navy">No matching residences</h2>
              <p className="mt-3 text-sm text-neutral-600">Adjust your filters or speak with an advisor about off-market homes.</p>
              <LuxButton as={Link} to="/properties" className="mt-8" data-testid="reset-filters">
                Reset Filters
              </LuxButton>
            </div>
          )}

          {pages > 1 && (
            <div className="mt-14 flex items-center justify-center gap-2" data-testid="pagination">
              {Array.from({ length: pages }).map((_, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => setPage(i)}
                  data-testid={`page-btn-${i + 1}`}
                  className={`h-11 w-11 rounded-full border text-sm transition-[background-color,color,border-color] duration-300 ${
                    page === i ? "border-navy bg-navy text-white" : "border-line text-navy hover:border-navy"
                  }`}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          )}
        </div>
      </section>

      <QuickViewModal property={quickView} open={Boolean(quickView)} onOpenChange={() => setQuickView(null)} />
    </main>
  );
}
