import { useState } from "react";
import { Link, useParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import {
  ChevronRight, BedDouble, Bath, Maximize, MapPin, CalendarDays, Check, Phone, Mail, Heart,
} from "lucide-react";
import { fetchProperty, formatArea, formatPrice } from "../lib/api";
import { LuxButton } from "../components/common/LuxButton";
import { Reveal } from "../components/common/Reveal";
import { useFavorites } from "../lib/useFavorites";
import { BRAND } from "../lib/content";

export default function PropertyDetail() {
  const { id } = useParams();
  const { data, isLoading } = useQuery({ queryKey: ["property", id], queryFn: () => fetchProperty(id) });
  const [activeImage, setActiveImage] = useState(0);
  const { isFavorite, toggle } = useFavorites();

  if (isLoading || !data) {
    return (
      <main className="container-lux pt-36 pb-24" data-testid="property-detail-loading">
        <div className="skeleton h-8 w-1/3 rounded" />
        <div className="skeleton mt-8 h-[420px] w-full rounded-2xl" />
      </main>
    );
  }

  const p = data.property;
  const similar = data.similar || [];

  return (
    <main className="pt-20" data-testid="property-detail-page">
      <section className="border-b border-line bg-beige py-14">
        <div className="container-lux">
          <nav className="flex items-center gap-2 text-xs text-neutral-500" data-testid="detail-breadcrumbs">
            <Link to="/" className="hover:text-navy">Home</Link>
            <ChevronRight size={13} />
            <Link to="/properties" className="hover:text-navy">Properties</Link>
            <ChevronRight size={13} />
            <span className="text-navy">{p.title}</span>
          </nav>
          <div className="mt-6 flex flex-wrap items-end justify-between gap-6">
            <div>
              <p className="overline">{p.type}</p>
              <h1 className="mt-3 font-display text-3xl font-light leading-tight tracking-tight text-navy sm:text-5xl">
                {p.title}
              </h1>
              <p className="mt-4 flex items-center gap-2 text-sm text-neutral-600">
                <MapPin size={15} strokeWidth={1.5} className="text-gold" /> {p.location}
              </p>
            </div>
            <div className="text-right">
              <p className="font-display text-4xl text-gold-dark" data-testid="detail-price">{formatPrice(p.price)}</p>
              <button
                type="button"
                onClick={() => toggle(p.id)}
                data-testid="detail-favorite-btn"
                className="mt-4 inline-flex items-center gap-2 rounded-full border border-line bg-white px-5 py-2.5 text-[11px] uppercase tracking-[0.16em] text-navy transition-colors duration-300 hover:border-navy"
              >
                <Heart size={14} strokeWidth={1.5} className={isFavorite(p.id) ? "fill-gold text-gold" : ""} />
                {isFavorite(p.id) ? "Saved" : "Save Property"}
              </button>
            </div>
          </div>
        </div>
      </section>

      <section className="bg-white py-14">
        <div className="container-lux grid gap-12 lg:grid-cols-[1.6fr_1fr]">
          <div>
            <Reveal className="overflow-hidden rounded-2xl">
              <img
                src={p.images[activeImage]}
                alt={p.title}
                className="h-[300px] w-full object-cover sm:h-[520px]"
                data-testid="detail-main-image"
              />
            </Reveal>
            <div className="mt-4 grid grid-cols-4 gap-4">
              {p.images.map((img, i) => (
                <button
                  key={img}
                  type="button"
                  onClick={() => setActiveImage(i)}
                  data-testid={`detail-thumb-${i}`}
                  className={`overflow-hidden rounded-xl border-2 transition-colors duration-300 ${
                    activeImage === i ? "border-gold" : "border-transparent"
                  }`}
                >
                  <img src={img} alt={`${p.title} view ${i + 1}`} loading="lazy" className="h-20 w-full object-cover sm:h-24" />
                </button>
              ))}
            </div>

            <div className="mt-12 grid grid-cols-2 gap-6 rounded-2xl border border-line bg-offwhite p-8 sm:grid-cols-4">
              {[
                { icon: BedDouble, label: "Bedrooms", value: p.beds || "—" },
                { icon: Bath, label: "Bathrooms", value: p.baths || "—" },
                { icon: Maximize, label: "Area", value: `${formatArea(p.area)} sqft` },
                { icon: CalendarDays, label: "Year Built", value: p.year_built },
              ].map(({ icon: Icon, label, value }) => (
                <div key={label}>
                  <Icon size={19} strokeWidth={1.4} className="text-gold" />
                  <p className="mt-3 font-display text-xl text-navy">{value}</p>
                  <p className="mt-1 text-[10px] uppercase tracking-[0.18em] text-neutral-500">{label}</p>
                </div>
              ))}
            </div>

            <div className="mt-12">
              <h2 className="font-display text-2xl text-navy">About This Residence</h2>
              <p className="mt-5 text-base leading-relaxed text-neutral-600">{p.description}</p>
            </div>

            <div className="mt-12">
              <h2 className="font-display text-2xl text-navy">Amenities</h2>
              <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {p.amenities.map((a) => (
                  <p key={a} className="flex items-center gap-3 text-sm text-neutral-700">
                    <span className="grid h-6 w-6 place-items-center rounded-full bg-gold/15 text-gold-dark">
                      <Check size={12} strokeWidth={2} />
                    </span>
                    {a}
                  </p>
                ))}
              </div>
            </div>
          </div>

          <aside className="lg:sticky lg:top-28 lg:self-start">
            <div className="rounded-2xl border border-line bg-white p-8 shadow-soft">
              <p className="overline">Listing Advisor</p>
              <h3 className="mt-3 font-display text-2xl text-navy">{p.agent}</h3>
              <p className="mt-2 text-sm text-neutral-600">Senior advisor for {p.city}</p>
              <div className="mt-7 space-y-3 border-t border-line pt-6 text-sm">
                <p className="flex items-center gap-3 text-neutral-700">
                  <Phone size={15} strokeWidth={1.5} className="text-gold" /> {BRAND.phone}
                </p>
                <p className="flex items-center gap-3 text-neutral-700">
                  <Mail size={15} strokeWidth={1.5} className="text-gold" /> {BRAND.email}
                </p>
              </div>
              <LuxButton as={Link} to="/#contact" className="mt-8 w-full" data-testid="detail-enquire-btn">
                Arrange a Viewing
              </LuxButton>
              <LuxButton as={Link} to="/properties" variant="outline" className="mt-3 w-full" data-testid="detail-back-btn">
                Back to Portfolio
              </LuxButton>
            </div>
          </aside>
        </div>
      </section>

      {similar.length > 0 && (
        <section className="bg-offwhite py-20">
          <div className="container-lux">
            <h2 className="font-display text-3xl font-light text-navy">Similar Residences</h2>
            <div className="mt-10 grid gap-7 sm:grid-cols-2 lg:grid-cols-3">
              {similar.map((s) => (
                <Link
                  key={s.id}
                  to={`/properties/${s.id}`}
                  data-testid={`similar-${s.id}`}
                  className="group overflow-hidden rounded-2xl border border-line bg-white transition-[transform,box-shadow] duration-500 hover:-translate-y-2 hover:shadow-lift"
                >
                  <div className="aspect-[4/3] overflow-hidden">
                    <img
                      src={s.images[0]}
                      alt={s.title}
                      loading="lazy"
                      className="h-full w-full object-cover transition-transform duration-[900ms] group-hover:scale-110"
                    />
                  </div>
                  <div className="p-6">
                    <h3 className="font-display text-lg text-navy">{s.title}</h3>
                    <p className="mt-2 text-xs text-neutral-500">{s.location}</p>
                    <p className="mt-3 font-display text-xl text-gold-dark">{formatPrice(s.price)}</p>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        </section>
      )}
    </main>
  );
}
