import { useState } from "react";
import { MapPin, Phone, Mail, Clock, Send } from "lucide-react";
import { toast } from "sonner";
import { Reveal } from "../common/Reveal";
import { LuxButton } from "../common/LuxButton";
import { BRAND, SERVICES } from "../../lib/content";
import { sendContact } from "../../lib/api";

const inputClass =
  "w-full rounded-xl border border-line bg-white px-5 py-3.5 text-sm text-navy placeholder:text-neutral-400 transition-[border-color,box-shadow] duration-300 focus:border-navy focus:outline-none focus:ring-1 focus:ring-navy/20";

const DETAILS = [
  { icon: MapPin, label: "Office", value: BRAND.address },
  { icon: Phone, label: "Phone", value: BRAND.phone },
  { icon: Mail, label: "Email", value: BRAND.email },
  { icon: Clock, label: "Working Hours", value: BRAND.hours },
];

export const Contact = () => {
  const [form, setForm] = useState({ name: "", email: "", phone: "", interest: SERVICES[0], message: "" });
  const [loading, setLoading] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    setLoading(true);
    try {
      const res = await sendContact(form);
      toast.success(res.message);
      setForm({ name: "", email: "", phone: "", interest: SERVICES[0], message: "" });
    } catch {
      toast.error("Something went wrong. Please check your details and try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="contact" className="bg-white py-24 lg:py-32" data-testid="contact-section">
      <div className="container-lux grid gap-14 lg:grid-cols-[1fr_1.1fr]">
        <Reveal>
          <p className="overline">Contact</p>
          <h2 className="mt-4 text-3xl font-light leading-[1.1] tracking-tight text-navy sm:text-4xl lg:text-[44px]">
            Book a Private Consultation
          </h2>
          <p className="mt-6 max-w-md text-base leading-relaxed text-neutral-600">
            Visit our Madison Avenue office or arrange a call at a time that suits you.
          </p>

          <div className="mt-10 space-y-6">
            {DETAILS.map(({ icon: Icon, label, value }) => (
              <div key={label} className="flex gap-4" data-testid={`contact-detail-${label.toLowerCase().replace(/\s+/g, "-")}`}>
                <span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl border border-gold/30 text-gold">
                  <Icon size={17} strokeWidth={1.4} />
                </span>
                <div>
                  <p className="text-[10px] uppercase tracking-[0.2em] text-neutral-500">{label}</p>
                  <p className="mt-1 text-sm text-navy">{value}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-10 overflow-hidden rounded-2xl border border-line" data-testid="contact-map">
            <iframe
              title="Luxora office location on Google Maps"
              src={`https://www.google.com/maps?q=${encodeURIComponent(BRAND.address)}&output=embed`}
              className="h-64 w-full"
              loading="lazy"
              referrerPolicy="no-referrer-when-downgrade"
              allowFullScreen
            />
          </div>
        </Reveal>

        <Reveal delay={0.12}>
          <form
            onSubmit={submit}
            className="rounded-2xl border border-line bg-offwhite p-8 shadow-soft lg:p-10"
            data-testid="contact-form"
          >
            <div className="grid gap-5 sm:grid-cols-2">
              <input
                required
                placeholder="Full name"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                className={inputClass}
                data-testid="contact-name"
              />
              <input
                required
                type="email"
                placeholder="Email address"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                className={inputClass}
                data-testid="contact-email"
              />
              <input
                placeholder="Phone number"
                value={form.phone}
                onChange={(e) => setForm({ ...form, phone: e.target.value })}
                className={inputClass}
                data-testid="contact-phone"
              />
              <select
                value={form.interest}
                onChange={(e) => setForm({ ...form, interest: e.target.value })}
                className={`${inputClass} cursor-pointer`}
                data-testid="contact-interest"
              >
                {SERVICES.map((s) => (
                  <option key={s}>{s}</option>
                ))}
              </select>
            </div>
            <textarea
              required
              rows={6}
              placeholder="Tell us about the home you are looking for"
              value={form.message}
              onChange={(e) => setForm({ ...form, message: e.target.value })}
              className={`${inputClass} mt-5 resize-none`}
              data-testid="contact-message"
            />
            <LuxButton type="submit" size="lg" disabled={loading} className="mt-7 w-full" data-testid="contact-submit">
              <Send size={15} strokeWidth={1.6} /> {loading ? "Sending..." : "Send Enquiry"}
            </LuxButton>
            <p className="mt-5 text-xs leading-relaxed text-neutral-500">
              We reply within one working day. Your details are never shared with third parties.
            </p>
          </form>
        </Reveal>
      </div>
    </section>
  );
};
