import { Link, useParams } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ChevronRight, CalendarDays, Clock, ArrowUpRight, Linkedin, Twitter, Link2 } from "lucide-react";
import { toast } from "sonner";
import { fetchPost } from "../lib/api";
import { Reveal } from "../components/common/Reveal";
import { LuxButton } from "../components/common/LuxButton";

const Block = ({ block }) => {
  if (block.type === "heading") {
    return <h2 className="mt-12 font-display text-2xl font-normal text-navy sm:text-3xl">{block.text}</h2>;
  }
  if (block.type === "quote") {
    return (
      <blockquote className="my-10 border-l-2 border-gold pl-7 font-display text-2xl font-light italic leading-relaxed text-navy">
        {block.text}
      </blockquote>
    );
  }
  if (block.type === "list") {
    return (
      <ul className="mt-6 space-y-3">
        {block.items.map((item) => (
          <li key={item} className="flex gap-3 text-base leading-relaxed text-neutral-700">
            <span className="mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-gold" />
            {item}
          </li>
        ))}
      </ul>
    );
  }
  return <p className="mt-6 text-base leading-relaxed text-neutral-700">{block.text}</p>;
};

export default function BlogDetail() {
  const { id } = useParams();
  const { data, isLoading } = useQuery({ queryKey: ["post", id], queryFn: () => fetchPost(id) });

  const share = () => {
    navigator.clipboard?.writeText(window.location.href);
    toast.success("Article link copied to clipboard.");
  };

  if (isLoading || !data) {
    return (
      <main className="container-lux pb-24 pt-36" data-testid="blog-detail-loading">
        <div className="skeleton h-8 w-2/3 rounded" />
        <div className="skeleton mt-8 h-[380px] w-full rounded-2xl" />
      </main>
    );
  }

  const post = data.post;
  const related = data.related || [];
  const formattedDate = new Date(post.date).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
  });

  return (
    <main className="pt-20" data-testid="blog-detail-page">
      <section className="border-b border-line bg-beige py-14">
        <div className="container-lux max-w-3xl">
          <nav className="flex items-center gap-2 text-xs text-neutral-500" data-testid="blog-breadcrumbs">
            <Link to="/" className="hover:text-navy">Home</Link>
            <ChevronRight size={13} />
            <Link to="/#blog" className="hover:text-navy">Blog</Link>
            <ChevronRight size={13} />
            <span className="text-navy">{post.category}</span>
          </nav>
          <p className="overline mt-8">{post.category}</p>
          <h1 className="mt-4 font-display text-3xl font-light leading-tight tracking-tight text-navy sm:text-5xl">
            {post.title}
          </h1>
          <p className="mt-6 flex flex-wrap items-center gap-5 text-xs text-neutral-500">
            <span className="flex items-center gap-1.5">
              <CalendarDays size={13} strokeWidth={1.5} className="text-gold" /> {formattedDate}
            </span>
            <span className="flex items-center gap-1.5">
              <Clock size={13} strokeWidth={1.5} className="text-gold" /> {post.read_time}
            </span>
            <span>By {post.author}</span>
          </p>
        </div>
      </section>

      <section className="bg-white py-14">
        <div className="container-lux max-w-3xl">
          <Reveal className="overflow-hidden rounded-2xl">
            <img src={post.image} alt={post.title} className="h-[280px] w-full object-cover sm:h-[440px]" data-testid="blog-hero-image" />
          </Reveal>

          <article className="mt-12" data-testid="blog-body">
            <p className="font-display text-2xl font-light leading-relaxed text-navy">{post.excerpt}</p>
            {post.content?.map((block, i) => (
              <Block key={i} block={block} />
            ))}
          </article>

          <div className="mt-12 flex flex-wrap items-center gap-3">
            {post.tags?.map((tag) => (
              <span key={tag} className="rounded-full border border-line px-4 py-1.5 text-[10px] uppercase tracking-[0.18em] text-neutral-600">
                {tag}
              </span>
            ))}
            <div className="ml-auto flex gap-2">
              {[Linkedin, Twitter].map((Icon, i) => (
                <a
                  key={i}
                  href="/#contact"
                  aria-label="Share article"
                  data-testid={`blog-share-${i}`}
                  className="grid h-10 w-10 place-items-center rounded-full border border-line text-navy transition-colors duration-300 hover:border-navy hover:bg-navy hover:text-white"
                >
                  <Icon size={14} strokeWidth={1.5} />
                </a>
              ))}
              <button
                type="button"
                onClick={share}
                aria-label="Copy article link"
                data-testid="blog-copy-link"
                className="grid h-10 w-10 place-items-center rounded-full border border-line text-navy transition-colors duration-300 hover:border-navy hover:bg-navy hover:text-white"
              >
                <Link2 size={14} strokeWidth={1.5} />
              </button>
            </div>
          </div>

          <div className="mt-14 flex flex-wrap items-center gap-6 rounded-2xl border border-line bg-offwhite p-8" data-testid="blog-author-box">
            {post.author_image && (
              <img src={post.author_image} alt={post.author} loading="lazy" className="h-20 w-20 rounded-full object-cover" />
            )}
            <div className="min-w-[200px] flex-1">
              <p className="overline">Written by</p>
              <h3 className="mt-2 font-display text-xl text-navy">{post.author}</h3>
              <p className="mt-1 text-sm text-neutral-600">{post.author_role}</p>
            </div>
            <LuxButton as={Link} to="/#contact" size="sm" data-testid="blog-author-cta">
              Speak to {post.author.split(" ")[0]}
            </LuxButton>
          </div>
        </div>
      </section>

      {related.length > 0 && (
        <section className="bg-offwhite py-20">
          <div className="container-lux">
            <h2 className="font-display text-3xl font-light text-navy">Continue Reading</h2>
            <div className="mt-10 grid gap-7 md:grid-cols-2">
              {related.map((r) => (
                <Link
                  key={r.id}
                  to={`/blog/${r.id}`}
                  data-testid={`related-post-${r.id}`}
                  className="group flex gap-6 overflow-hidden rounded-2xl border border-line bg-white p-5 transition-[transform,box-shadow] duration-500 hover:-translate-y-1.5 hover:shadow-lift"
                >
                  <img src={r.image} alt={r.title} loading="lazy" className="h-28 w-32 shrink-0 rounded-xl object-cover" />
                  <div>
                    <p className="overline">{r.category}</p>
                    <h3 className="mt-2 font-display text-lg leading-snug text-navy">{r.title}</h3>
                    <span className="link-underline mt-3 inline-flex items-center gap-2 text-[11px] uppercase tracking-[0.18em] text-navy">
                      Read More <ArrowUpRight size={13} strokeWidth={1.5} />
                    </span>
                  </div>
                </Link>
              ))}
            </div>
          </div>
        </section>
      )}
    </main>
  );
}
