import { useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { ChevronRight, HeartOff } from "lucide-react";
import { fetchPropertiesByIds } from "../lib/api";
import { useFavorites } from "../lib/useFavorites";
import { PropertyCard, PropertyCardSkeleton } from "../components/PropertyCard";
import { QuickViewModal } from "../components/QuickViewModal";
import { StaggerGroup } from "../components/common/Reveal";
import { LuxButton } from "../components/common/LuxButton";

export default function SavedProperties() {
  const { favorites, toggle, isFavorite } = useFavorites();
  const [quickView, setQuickView] = useState(null);

  const { data, isLoading } = useQuery({
    queryKey: ["saved", favorites],
    queryFn: () => fetchPropertiesByIds(favorites),
    enabled: favorites.length > 0,
  });

  const items = favorites.length === 0 ? [] : data?.items || [];

  return (
    <main className="pt-20" data-testid="saved-page">
      <section className="border-b border-line bg-beige py-16">
        <div className="container-lux">
          <nav className="flex items-center gap-2 text-xs text-neutral-500" data-testid="saved-breadcrumbs">
            <Link to="/" className="hover:text-navy">Home</Link>
            <ChevronRight size={13} />
            <span className="text-navy">Saved Properties</span>
          </nav>
          <h1 className="mt-6 font-display text-4xl font-light leading-tight tracking-tight text-navy sm:text-5xl">
            Saved Properties
          </h1>
          <p className="mt-4 max-w-xl text-base text-neutral-600" data-testid="saved-count">
            {favorites.length === 0
              ? "You have not saved any residences yet."
              : `${favorites.length} residence${favorites.length > 1 ? "s" : ""} kept for your shortlist.`}
          </p>
        </div>
      </section>

      <section className="bg-offwhite py-16 lg:py-24">
        <div className="container-lux">
          {favorites.length === 0 ? (
            <div className="rounded-2xl border border-line bg-white p-16 text-center" data-testid="saved-empty">
              <span className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-gold/30 text-gold">
                <HeartOff size={22} strokeWidth={1.3} />
              </span>
              <h2 className="mt-7 font-display text-2xl text-navy">Your shortlist is empty</h2>
              <p className="mt-3 text-sm text-neutral-600">
                Tap the heart on any residence to keep it here — your shortlist stays on this device.
              </p>
              <LuxButton as={Link} to="/properties" className="mt-8" data-testid="saved-browse-btn">
                Browse Portfolio
              </LuxButton>
            </div>
          ) : (
            <StaggerGroup
              key={`${favorites.length}-${isLoading}`}
              className="grid gap-7 sm:grid-cols-2 lg:grid-cols-3"
            >
              {isLoading
                ? Array.from({ length: Math.min(favorites.length, 3) }).map((_, i) => <PropertyCardSkeleton key={i} />)
                : items.map((property, index) => (
                    <PropertyCard
                      key={property.id}
                      property={property}
                      index={index}
                      isFavorite={isFavorite(property.id)}
                      onToggleFavorite={toggle}
                      onQuickView={setQuickView}
                    />
                  ))}
            </StaggerGroup>
          )}
        </div>
      </section>

      <QuickViewModal property={quickView} open={Boolean(quickView)} onOpenChange={() => setQuickView(null)} />
    </main>
  );
}
