import { useQuery } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { ArrowUpRight, CalendarDays } from "lucide-react";
import { fetchPosts } from "../../lib/api";
import { SectionHeading } from "../common/SectionHeading";
import { StaggerGroup, StaggerItem } from "../common/Reveal";

export const Blog = () => {
  const { data: posts = [] } = useQuery({ queryKey: ["posts"], queryFn: fetchPosts });

  return (
    <section id="blog" className="bg-white py-24 lg:py-32" data-testid="blog-section">
      <div className="container-lux">
        <SectionHeading
          overline="Latest Blog"
          title="Real Estate Insights"
          description="Market notes, design thinking and buyer guidance from our advisory team."
          align="center"
        />

        <StaggerGroup key={posts.length} className="mt-14 grid gap-7 md:grid-cols-3">
          {posts.map((post) => (
            <StaggerItem key={post.id}>
              <article
                className="group flex h-full flex-col overflow-hidden rounded-2xl border border-line bg-white transition-[transform,box-shadow] duration-500 hover:-translate-y-2 hover:shadow-lift"
                data-testid={`blog-card-${post.id}`}
              >
                <Link to={`/blog/${post.id}`} className="relative block aspect-[16/10] overflow-hidden">
                  <img
                    src={post.image}
                    alt={post.title}
                    loading="lazy"
                    className="h-full w-full object-cover transition-transform duration-[900ms] ease-out group-hover:scale-110"
                  />
                  <span className="absolute left-4 top-4 rounded-full bg-white/90 px-3 py-1 text-[10px] uppercase tracking-[0.18em] text-navy backdrop-blur">
                    {post.category}
                  </span>
                </Link>
                <div className="p-7">
                  <p className="flex items-center gap-4 text-[11px] text-neutral-500">
                    <span className="flex items-center gap-1.5">
                      <CalendarDays size={13} strokeWidth={1.5} className="text-gold" />
                      {new Date(post.date).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </span>
                    <span>{post.read_time}</span>
                  </p>
                  <h3 className="mt-4 font-display text-xl leading-snug text-navy">
                    <Link to={`/blog/${post.id}`} className="transition-colors duration-300 hover:text-gold-dark">
                      {post.title}
                    </Link>
                  </h3>
                  <p className="mt-3 text-sm leading-relaxed text-neutral-600">{post.excerpt}</p>
                  <Link
                    to={`/blog/${post.id}`}
                    data-testid={`blog-read-${post.id}`}
                    className="link-underline mt-6 inline-flex items-center gap-2 text-[11px] uppercase tracking-[0.18em] text-navy"
                  >
                    Read More <ArrowUpRight size={14} strokeWidth={1.5} />
                  </Link>
                </div>
              </article>
            </StaggerItem>
          ))}
        </StaggerGroup>
      </div>
    </section>
  );
};
