import { Link } from "react-router-dom";
import { Heart, BedDouble, Bath, Maximize, MapPin, ArrowUpRight, Eye } from "lucide-react";
import { motion } from "framer-motion";
import { formatArea, formatPrice } from "../lib/api";

export const PropertyCard = ({ property, isFavorite, onToggleFavorite, onQuickView, index = 0 }) => (
  <motion.article
    variants={{ hidden: { opacity: 0, y: 34 }, show: { opacity: 1, y: 0 } }}
    transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
    className="group relative flex flex-col overflow-hidden rounded-2xl border border-line bg-white shadow-soft transition-[transform,box-shadow] duration-500 hover:-translate-y-2 hover:shadow-lift"
    data-testid={`property-card-${property.id}`}
  >
    <div className="relative aspect-[4/3] overflow-hidden">
      <img
        src={property.images[0]}
        alt={property.title}
        loading={index < 3 ? "eager" : "lazy"}
        className="h-full w-full object-cover transition-transform duration-[900ms] ease-out group-hover:scale-110"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-navy-deep/60 via-transparent to-transparent opacity-0 transition-opacity duration-500 group-hover:opacity-100" />

      <div className="absolute left-4 top-4 flex gap-2">
        {property.tags.slice(0, 2).map((tag) => (
          <span
            key={tag}
            className="rounded-full bg-white/90 px-3 py-1 text-[10px] uppercase tracking-[0.18em] text-navy backdrop-blur"
          >
            {tag}
          </span>
        ))}
      </div>

      <button
        type="button"
        aria-label={isFavorite ? "Remove from saved properties" : "Save property"}
        aria-pressed={isFavorite}
        onClick={() => onToggleFavorite(property.id)}
        data-testid={`favorite-btn-${property.id}`}
        className="absolute right-4 top-4 grid h-10 w-10 place-items-center rounded-full bg-white/90 text-navy backdrop-blur transition-[background-color,color,transform] duration-300 hover:scale-110 hover:bg-navy hover:text-white"
      >
        <Heart size={16} strokeWidth={1.5} className={isFavorite ? "fill-gold text-gold" : ""} />
      </button>

      <div className="absolute inset-x-4 bottom-4 flex translate-y-4 gap-2 opacity-0 transition-[opacity,transform] duration-500 group-hover:translate-y-0 group-hover:opacity-100">
        <button
          type="button"
          onClick={() => onQuickView(property)}
          data-testid={`quick-view-btn-${property.id}`}
          className="flex flex-1 items-center justify-center gap-2 rounded-full bg-white/90 px-4 py-2.5 text-[11px] uppercase tracking-[0.16em] text-navy backdrop-blur transition-colors duration-300 hover:bg-gold hover:text-navy-deep"
        >
          <Eye size={14} strokeWidth={1.5} /> Quick View
        </button>
      </div>
    </div>

    <div className="flex flex-1 flex-col p-6">
      <h3 className="font-display text-xl leading-snug text-navy">{property.title}</h3>
      <p className="mt-2 flex items-center gap-1.5 text-xs text-neutral-500">
        <MapPin size={13} strokeWidth={1.5} /> {property.location}
      </p>
      <p className="mt-4 font-display text-2xl text-gold-dark">{formatPrice(property.price)}</p>

      <div className="mt-5 flex flex-wrap items-center gap-x-5 gap-y-2 border-t border-line pt-5 text-xs text-neutral-600">
        {property.beds > 0 && (
          <span className="flex items-center gap-1.5">
            <BedDouble size={15} strokeWidth={1.5} className="text-gold" /> {property.beds} Beds
          </span>
        )}
        {property.baths > 0 && (
          <span className="flex items-center gap-1.5">
            <Bath size={15} strokeWidth={1.5} className="text-gold" /> {property.baths} Baths
          </span>
        )}
        <span className="flex items-center gap-1.5">
          <Maximize size={15} strokeWidth={1.5} className="text-gold" /> {formatArea(property.area)} sqft
        </span>
      </div>

      <Link
        to={`/properties/${property.id}`}
        data-testid={`view-details-${property.id}`}
        className="mt-6 flex items-center justify-between rounded-full border border-line px-5 py-3 text-[11px] uppercase tracking-[0.18em] text-navy transition-[background-color,color,border-color] duration-300 hover:border-navy hover:bg-navy hover:text-white"
      >
        View Details
        <ArrowUpRight size={15} strokeWidth={1.5} />
      </Link>
    </div>
  </motion.article>
);

export const PropertyCardSkeleton = () => (
  <div className="overflow-hidden rounded-2xl border border-line bg-white">
    <div className="skeleton aspect-[4/3] w-full" />
    <div className="space-y-3 p-6">
      <div className="skeleton h-5 w-3/4 rounded" />
      <div className="skeleton h-3 w-1/2 rounded" />
      <div className="skeleton h-7 w-2/5 rounded" />
      <div className="skeleton h-10 w-full rounded-full" />
    </div>
  </div>
);
