import { cn } from "../../lib/utils";

const VARIANTS = {
  navy: "bg-navy text-white hover:bg-navy-deep",
  gold: "bg-gold text-navy-deep hover:bg-gold-light",
  outline: "bg-transparent text-navy border border-navy/25 hover:border-navy hover:bg-navy hover:text-white",
  ghost: "bg-white/90 text-navy border border-white/60 hover:bg-white",
};

const SIZES = {
  sm: "h-10 px-5 text-xs",
  md: "h-12 px-7 text-[13px]",
  lg: "h-14 px-9 text-sm",
};

export const LuxButton = ({
  as: Tag = "button",
  variant = "navy",
  size = "md",
  className = "",
  children,
  onClick,
  ...props
}) => {
  const handleClick = (event) => {
    const host = event.currentTarget;
    const rect = host.getBoundingClientRect();
    const span = document.createElement("span");
    const size = Math.max(rect.width, rect.height);
    span.className = "ripple";
    span.style.width = span.style.height = `${size}px`;
    span.style.left = `${event.clientX - rect.left - size / 2}px`;
    span.style.top = `${event.clientY - rect.top - size / 2}px`;
    host.appendChild(span);
    setTimeout(() => span.remove(), 650);
    onClick?.(event);
  };

  return (
    <Tag
      onClick={handleClick}
      className={cn(
        "btn-ripple inline-flex items-center justify-center gap-2 rounded-full uppercase tracking-[0.16em] font-medium",
        "transition-[background-color,color,border-color,box-shadow,transform] duration-300 ease-out",
        "hover:-translate-y-0.5 hover:shadow-lift active:translate-y-0",
        VARIANTS[variant],
        SIZES[size],
        className
      )}
      {...props}
    >
      {children}
    </Tag>
  );
};
