import { useQuery } from "@tanstack/react-query";
import { Users, Home, Globe2, Award } from "lucide-react";
import { fetchStats } from "../../lib/api";
import { Counter } from "../common/Counter";
import { StaggerGroup, StaggerItem } from "../common/Reveal";

const CONFIG = [
  { key: "happy_clients", label: "Happy Clients", icon: Users, suffix: "+" },
  { key: "properties_sold", label: "Properties Sold", icon: Home, suffix: "+" },
  { key: "cities_covered", label: "Cities Covered", icon: Globe2, suffix: "+" },
  { key: "years_experience", label: "Years Experience", icon: Award, suffix: "" },
];

export const Statistics = () => {
  const { data } = useQuery({ queryKey: ["stats"], queryFn: fetchStats });

  return (
    <section className="bg-white py-20" data-testid="stats-section">
      <div className="container-lux">
        <StaggerGroup key={data ? "ready" : "loading"} className="grid divide-y divide-line rounded-2xl border border-line bg-beige sm:grid-cols-2 sm:divide-x lg:grid-cols-4 lg:divide-y-0">
          {CONFIG.map(({ key, label, icon: Icon, suffix }) => (
            <StaggerItem key={key}>
              <div className="group flex items-center gap-5 p-9" data-testid={`stat-${key}`}>
                <span className="grid h-14 w-14 shrink-0 place-items-center rounded-2xl border border-gold/30 bg-white text-gold transition-[background-color,color] duration-500 group-hover:bg-navy group-hover:text-gold-light">
                  <Icon size={22} strokeWidth={1.3} />
                </span>
                <div>
                  <p className="font-display text-4xl font-light text-navy">
                    <Counter value={data?.[key] || 0} suffix={suffix} />
                  </p>
                  <p className="mt-1 text-[10px] uppercase tracking-[0.2em] text-neutral-500">{label}</p>
                </div>
              </div>
            </StaggerItem>
          ))}
        </StaggerGroup>
      </div>
    </section>
  );
};
