import { Link } from "react-router-dom";
import { BedDouble, Bath, Maximize, MapPin, CalendarDays } from "lucide-react";
import { Dialog, DialogContent, DialogTitle } from "./ui/dialog";
import { LuxButton } from "./common/LuxButton";
import { formatArea, formatPrice } from "../lib/api";

export const QuickViewModal = ({ property, open, onOpenChange }) => (
  <Dialog open={open} onOpenChange={onOpenChange}>
    <DialogContent
      className="max-w-3xl overflow-hidden rounded-2xl border-line p-0"
      data-testid="quick-view-modal"
    >
      {property && (
        <div className="grid md:grid-cols-2">
          <img src={property.images[0]} alt={property.title} className="h-56 w-full object-cover md:h-full" />
          <div className="p-8">
            <p className="overline">{property.type}</p>
            <DialogTitle className="mt-3 font-display text-3xl font-light leading-tight text-navy">
              {property.title}
            </DialogTitle>
            <p className="mt-3 flex items-center gap-1.5 text-xs text-neutral-500">
              <MapPin size={13} strokeWidth={1.5} /> {property.location}
            </p>
            <p className="mt-5 font-display text-3xl text-gold-dark">{formatPrice(property.price)}</p>
            <p className="mt-5 text-sm leading-relaxed text-neutral-600">{property.description}</p>

            <div className="mt-6 grid grid-cols-2 gap-4 border-t border-line pt-6 text-xs text-neutral-600">
              <span className="flex items-center gap-2">
                <BedDouble size={15} strokeWidth={1.5} className="text-gold" /> {property.beds} Bedrooms
              </span>
              <span className="flex items-center gap-2">
                <Bath size={15} strokeWidth={1.5} className="text-gold" /> {property.baths} Bathrooms
              </span>
              <span className="flex items-center gap-2">
                <Maximize size={15} strokeWidth={1.5} className="text-gold" /> {formatArea(property.area)} sqft
              </span>
              <span className="flex items-center gap-2">
                <CalendarDays size={15} strokeWidth={1.5} className="text-gold" /> Built {property.year_built}
              </span>
            </div>

            <LuxButton
              as={Link}
              to={`/properties/${property.id}`}
              className="mt-8 w-full"
              data-testid="quick-view-details-link"
              onClick={() => onOpenChange(false)}
            >
              View Full Details
            </LuxButton>
          </div>
        </div>
      )}
    </DialogContent>
  </Dialog>
);
